import{_ as a,o as t,c as s,ae as i}from"./chunks/framework.B2ul6ABY.js";const g=JSON.parse('{"title":"Saivage v3","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function n(r,e,l,c,h,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="saivage-v3" tabindex="-1">Saivage v3 <a class="header-anchor" href="#saivage-v3" aria-label="Permalink to &quot;Saivage v3&quot;">​</a></h1><p>An autonomous multi-agent system for software development.</p><h2 id="what-is-saivage" tabindex="-1">What is Saivage? <a class="header-anchor" href="#what-is-saivage" aria-label="Permalink to &quot;What is Saivage?&quot;">​</a></h2><p>Saivage is an autonomous multi-agent system that uses a <strong>Planner → Manager → Workers</strong> architecture to execute software development tasks. It maintains a persistent card store, supports plan-driven execution, and provides a Fastify-based API server with WebSocket events.</p><h2 id="quick-links" tabindex="-1">Quick Links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick Links&quot;">​</a></h2><ul><li><strong><a href="/docs/install.html">Installation Guide</a></strong> — Set up Saivage v3 from a clean checkout</li><li><strong><a href="/docs/configuration.html">Configuration Reference</a></strong> — Configure models, providers, MCP servers, Telegram, and notifications</li><li><strong><a href="/docs/operation.html">Operation Guide</a></strong> — Runtime management, API usage, backup, recovery, and web verification commands</li><li><strong><a href="/docs/operator-runbook.html">Operator Runbook</a></strong> — Day-to-day operator procedures and local verification commands</li><li><strong><a href="/docs/troubleshooting.html">Troubleshooting</a></strong> — Common issues and their solutions</li><li><strong><a href="/docs/release-checklist.html">Release Checklist</a></strong> — Steps to create a new release</li></ul><h2 id="verifying-the-web-control-room" tabindex="-1">Verifying the Web Control Room <a class="header-anchor" href="#verifying-the-web-control-room" aria-label="Permalink to &quot;Verifying the Web Control Room&quot;">​</a></h2><p>The Web Control Room SPA can be verified independently of the backend test suite using root-level npm scripts. See the <strong><a href="/docs/operation.html#web-verification-commands">Operation Guide → Web Verification Commands</a></strong> for the full set of commands, or run a quick sweep:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web:typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web:test:sweep</span></span></code></pre></div><p>These commands exercise the SPA&#39;s views, stores, and TypeScript types without touching backend agent logic or MCP integration tests.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>Saivage uses a multi-agent architecture with these key roles:</p><ul><li><strong>Planner</strong> — Top-level strategist that creates multi-stage plans</li><li><strong>Manager</strong> — Tactical executor that decomposes stages into tasks</li><li><strong>Coder</strong> — One-shot coding agent for code modifications</li><li><strong>Researcher</strong> — One-shot agent for information gathering</li></ul><p>The system maintains all state in a project-local <code>.saivage</code> directory using a JSON-based card store.</p>`,14)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
